    options.customDiffConfig = {
      threshold: 0.01, // Set custom threshold for image comparison
    };
    return cy.matchImageSnapshot(options);
  });

  // Custom task to capture a screenshot and return the file path
  Cypress.Commands.add("capture:screenshot", (options) => {
    return new Cypress.Promise((resolve, reject) => {
      captureScreenshot(options, (error, result) => {
        if (error) {
